    "about.hero": "Eesti suurim lao- ja logistikaplatvorm",
    "about.heroDesc": "Ruumly koondab Eesti parimad laopinnad, kolimisteenused ja haagiserendi pakkumised ühte kohta.",
    "about.mission": "Meie missioon",
    "about.missionP1": "Ruumly loodi eesmärgiga muuta laopinna ja logistikateenuste leidmine Eestis lihtsamaks, kiiremaks ja läbipaistvamaks. Enne meid pidi klient helistama kümnele ettevõttele, et leida sobiv pakkumine. Nüüd saab kõik ühest kohast.",
