    // Terms page
    "terms.title": "Kasutustingimused",
    "terms.validFrom": "Kehtivad alates: 21. märts 2026",
    "terms.s1.title": "1. Üldtingimused",
    "terms.s1.text": "Käesolevad kasutustingimused reguleerivad Ruumly platvormi (ruumly.eu) kasutamist. Platvormi kasutades nõustute nende tingimustega. Ruumly on Ruumly OÜ (registrikood: 12345678) hallatav teenus.",
    "terms.s2.title": "2. Teenuse kirjeldus",
    "terms.s2.text": "Ruumly on veebipõhine platvorm, mis koondab laopindade, kolimisteenuste ja haagiserendi pakkumised ühte kohta. Platvorm võimaldab kasutajatel otsida, võrrelda ja broneerida teenuseid meie partnerettevõtetelt.",
    "terms.s3.title": "3. Kasutajakonto",
    "terms.s3.text": "Konto loomiseks peate olema vähemalt 18-aastane. Vastutate oma konto turvalisuse ja kõigi konto kaudu tehtud toimingute eest. Teavitage meid viivitamatult igasugusest volitamata juurdepääsust.",
    "terms.s4.title": "4. Broneeringud ja tellimused",
    "terms.s4.text": "Broneeringud on siduvad alates kinnitamise hetkest. Tühistamistingimused sõltuvad konkreetsest teenusepakkujast ja on nähtavad enne broneerimist. Ruumly ei vastuta teenusepakkuja poolt osutatud teenuste kvaliteedi eest.",
    "terms.s5.title": "5. Hinnad ja maksed",
    "terms.s5.text": "Kõik platvormil kuvatud hinnad sisaldavad käibemaksu, kui pole märgitud teisiti. Ruumly jätab endale õiguse hindu muuta, kuid juba kinnitatud broneeringute hinnad jäävad samaks.",
    "terms.s6.title": "6. Vastutuse piiramine",
    "terms.s6.text": "Ruumly tegutseb vahendusplatvormina ja ei vastuta teenusepakkujate poolt põhjustatud kahju eest. Meie vastutus on piiratud kasutaja poolt makstud vahendustasu suurusega.",
    "terms.s7.title": "7. Tingimuste muutmine",
    "terms.s7.text": "Jätame endale õiguse neid tingimusi muuta, teavitades kasutajaid muudatustest ette vähemalt 30 päeva. Platvormi jätkuv kasutamine pärast muudatusi tähendab nõustumist uute tingimustega.",
    "terms.s8.title": "8. Kontakt",
    "terms.s8.text": "Küsimuste korral võtke meiega ühendust: info@ruumly.eu",

    // Privacy page
    "privacy.title": "Privaatsuspoliitika",
    "privacy.validFrom": "Kehtivad alates: 21. märts 2026",
    "privacy.s1.title": "1. Vastutav töötleja",
    "privacy.s1.text": "Ruumly OÜ (registrikood: 12345678), aadress: Tallinn, Eesti. Kontakt: info@ruumly.eu",
    "privacy.s2.title": "2. Milliseid andmeid kogume",
    "privacy.s2.items": "Nimi ja kontaktandmed (e-post, telefon)|Konto andmed (kasutajanimi, parool räsina)|Broneeringuandmed ja teenuste kasutamise ajalugu|Asukohaandmed (otsinguteks)|Seadme ja veebilehitseja andmed (küpsiste kaudu)|Makse andmed (töödeldakse turvaliste makseteenuse pakkujate kaudu)",
    "privacy.s3.title": "3. Andmetöötluse eesmärgid",
    "privacy.s3.items": "Teenuse osutamine ja broneeringute haldamine|Kasutajakogemuse parandamine|Turunduskommunikatsioon (ainult nõusolekul)|Õiguslike kohustuste täitmine|Platvormi turvalisuse tagamine",
    "privacy.s4.title": "4. Andmete jagamine",
    "privacy.s4.text": "Jagame teie andmeid ainult teenusepakkujatega, kelle teenust olete broneerinud, ning usaldusväärse IT- ja makseteenuse pakkujatega. Me ei müü teie isikuandmeid kolmandatele osapooltele.",
    "privacy.s5.title": "5. Teie õigused",
    "privacy.s5.intro": "GDPR kohaselt on teil õigus:",
    "privacy.s5.items": "Tutvuda oma isikuandmetega|Nõuda andmete parandamist või kustutamist|Piirata andmetöötlust|Andmete ülekandmist|Esitada kaebus Andmekaitse Inspektsioonile",
    "privacy.s6.title": "6. Andmete säilitamine",
    "privacy.s6.text": "Säilitame teie isikuandmeid nii kaua, kui see on vajalik teenuse osutamiseks või õiguslike kohustuste täitmiseks. Konto kustutamisel eemaldame teie andmed 30 päeva jooksul.",
    "privacy.s7.title": "7. Kontakt",
    "privacy.s7.text": "Andmekaitsega seotud küsimuste korral: info@ruumly.eu",

    // Cookie page
    "cookie.title": "Küpsiste poliitika",
    "cookie.validFrom": "Kehtivad alates: 21. märts 2026",
    "cookie.s1.title": "1. Mis on küpsised?",
    "cookie.s1.text": "Küpsised on väikesed tekstifailid, mida veebileht salvestab teie seadmesse. Need aitavad meil meeles pidada teie eelistusi ja parandada kasutajakogemust.",
    "cookie.s2.title": "2. Milliseid küpsiseid kasutame?",
    "cookie.essential": "Vajalikud küpsised",
    "cookie.essentialDesc": "Platvormi põhifunktsionaalsus: sisselogimine, keele-eelistus, ostukorv. Neid ei saa keelata.",
    "cookie.analytics": "Analüütilised küpsised",
    "cookie.analyticsDesc": "Aitavad meil mõista, kuidas kasutajad platvormi kasutavad. Kasutame Google Analytics teenust.",
    "cookie.marketing": "Turundusküpsised",
    "cookie.marketingDesc": "Võimaldavad näidata teile asjakohaseid reklaame ja mõõta kampaaniate efektiivsust.",
    "cookie.functional": "Funktsionaalsed küpsised",
    "cookie.functionalDesc": "Meeles pidamine: keele-eelistus, salvestatud otsingud, viimati vaadatud teenused.",
    "cookie.s3.title": "3. Küpsiste haldamine",
    "cookie.s3.text": "Saate küpsiste seadeid hallata oma veebilehitseja seadetes. Küpsiste keelamine võib piirata platvormi funktsionaalsust.",
    "cookie.s4.title": "4. Kolmandate osapoolte küpsised",
    "cookie.s4.text": "Meie platvormil võivad küpsiseid paigaldada ka kolmandad osapooled nagu Google Analytics, Google Maps ja sotsiaalmeedia platvormid. Nende küpsiste kohta kehtivad vastavate teenusepakkujate privaatsuspoliitikad.",
    "cookie.s5.title": "5. Kontakt",
    "cookie.s5.text": "Küpsistega seotud küsimuste korral: info@ruumly.eu",

