    "terms.title": "Terms of service",
    "terms.validFrom": "Valid from: March 21, 2026",
    "terms.s1.title": "1. General terms",
    "terms.s1.text": "These terms of service govern the use of the Ruumly platform (ruumly.eu). By using the platform, you agree to these terms. Ruumly is a service managed by Ruumly OÜ (registration code: 12345678).",
    "terms.s2.title": "2. Service description",
    "terms.s2.text": "Ruumly is a web-based platform that brings together storage, moving service, and trailer rental offers in one place. The platform allows users to search, compare, and book services from our partner companies.",
    "terms.s3.title": "3. User account",
    "terms.s3.text": "You must be at least 18 years old to create an account. You are responsible for the security of your account and all actions taken through it. Notify us immediately of any unauthorized access.",
    "terms.s4.title": "4. Bookings and orders",
    "terms.s4.text": "Bookings are binding from the moment of confirmation. Cancellation terms depend on the specific service provider and are visible before booking. Ruumly is not responsible for the quality of services provided by service providers.",
    "terms.s5.title": "5. Prices and payments",
    "terms.s5.text": "All prices displayed on the platform include VAT, unless otherwise stated. Ruumly reserves the right to change prices, but prices for already confirmed bookings remain the same.",
    "terms.s6.title": "6. Limitation of liability",
    "terms.s6.text": "Ruumly acts as an intermediary platform and is not responsible for damages caused by service providers. Our liability is limited to the mediation fee paid by the user.",
    "terms.s7.title": "7. Changes to terms",
    "terms.s7.text": "We reserve the right to change these terms, notifying users of changes at least 30 days in advance. Continued use of the platform after changes means acceptance of the new terms.",
    "terms.s8.title": "8. Contact",
    "terms.s8.text": "For questions, contact us: info@ruumly.eu",

    "privacy.title": "Privacy policy",
    "privacy.validFrom": "Valid from: March 21, 2026",
    "privacy.s1.title": "1. Data controller",
    "privacy.s1.text": "Ruumly OÜ (registration code: 12345678), address: Tallinn, Estonia. Contact: info@ruumly.eu",
    "privacy.s2.title": "2. Data we collect",
    "privacy.s2.items": "Name and contact details (email, phone)|Account data (username, password hash)|Booking data and service usage history|Location data (for searches)|Device and browser data (via cookies)|Payment data (processed through secure payment providers)",
    "privacy.s3.title": "3. Purposes of data processing",
    "privacy.s3.items": "Service provision and booking management|Improving user experience|Marketing communications (with consent only)|Fulfilling legal obligations|Ensuring platform security",
    "privacy.s4.title": "4. Data sharing",
    "privacy.s4.text": "We share your data only with service providers whose service you have booked, and with trusted IT and payment service providers. We do not sell your personal data to third parties.",
    "privacy.s5.title": "5. Your rights",
    "privacy.s5.intro": "Under GDPR, you have the right to:",
    "privacy.s5.items": "Access your personal data|Request correction or deletion of data|Restrict data processing|Data portability|File a complaint with the Data Protection Inspectorate",
    "privacy.s6.title": "6. Data retention",
    "privacy.s6.text": "We retain your personal data for as long as necessary for providing the service or fulfilling legal obligations. Upon account deletion, we remove your data within 30 days.",
    "privacy.s7.title": "7. Contact",
    "privacy.s7.text": "For data protection questions: info@ruumly.eu",

    "cookie.title": "Cookie policy",
    "cookie.validFrom": "Valid from: March 21, 2026",
    "cookie.s1.title": "1. What are cookies?",
    "cookie.s1.text": "Cookies are small text files that a website stores on your device. They help us remember your preferences and improve user experience.",
    "cookie.s2.title": "2. What cookies do we use?",
    "cookie.essential": "Essential cookies",
    "cookie.essentialDesc": "Core platform functionality: login, language preference, shopping cart. These cannot be disabled.",
    "cookie.analytics": "Analytical cookies",
    "cookie.analyticsDesc": "Help us understand how users use the platform. We use Google Analytics.",
    "cookie.marketing": "Marketing cookies",
    "cookie.marketingDesc": "Allow showing you relevant ads and measuring campaign effectiveness.",
    "cookie.functional": "Functional cookies",
    "cookie.functionalDesc": "Remembering: language preference, saved searches, recently viewed services.",
    "cookie.s3.title": "3. Managing cookies",
    "cookie.s3.text": "You can manage cookie settings in your browser settings. Disabling cookies may limit platform functionality.",
    "cookie.s4.title": "4. Third-party cookies",
    "cookie.s4.text": "Third parties such as Google Analytics, Google Maps, and social media platforms may also place cookies on our platform. Their cookies are governed by the respective providers' privacy policies.",
    "cookie.s5.title": "5. Contact",
    "cookie.s5.text": "For cookie-related questions: info@ruumly.eu",

