    "faq.title": "Часто задаваемые вопросы",
    "faq.subtitle": "Найдите ответы на самые частые вопросы.",
    "faq.general": "Общие вопросы",
    "faq.bookings": "Бронирование",
    "faq.providers": "Для партнёров",
    "faq.whatIsRuumly": "Что такое Ruumly?",
    "faq.whatIsRuumlyA": "Ruumly — крупнейшая платформа складов и логистики Эстонии. Бронируйте через нас и экономьте до {discount}%.",
    "faq.isFree": "Действительно ли через Ruumly дешевле?",
    "faq.isFreeA": "Да! Наши партнёрские цены до {discount}% ниже, чем при бронировании напрямую. Поиск и бронирование бесплатны для пользователей.",
    "faq.howWorks": "Как работает бронирование?",
    "faq.howWorksA": "Выберите услугу, даты и доп. услуги, введите данные и подтвердите. Подтверждение придёт на email.",
    "faq.whichCities": "В каких городах работает сервис?",
    "faq.whichCitiesA": "Ruumly работает по всей Эстонии — Таллинн, Тарту, Пярну, Нарва, Вильянди и другие города.",
    "faq.howToBook": "Как забронировать склад?",
    "faq.howToBookA": "Выберите склад, нажмите 'Забронировать' и пройдите процесс бронирования. Оплата: перевод, карта или счёт.",
    "faq.isCheaper": "Почему через Ruumly дешевле?",
    "faq.isCheaperA": "Наши партнёры предлагают скидку через Ruumly, так как мы приводим им клиентов. Эта экономия передаётся вам.",
    "faq.canCancel": "Можно ли отменить бронирование?",
    "faq.canCancelA": "Условия отмены зависят от поставщика и видны до бронирования.",
    "faq.howFast": "Как быстро подтверждается бронирование?",
    "faq.howFastA": "Большинство бронирований подтверждается автоматически. В некоторых случаях — в течение 1-2 часов.",
    "faq.howToJoin": "Как стать партнёром?",
    "faq.howToJoinA": "Перейдите на страницу 'Партнёрам', заполните форму регистрации и добавьте свою локацию. К каждой локации можно добавить несколько типов единиц — например, разные размеры или ценовые категории. Наша команда свяжется с вами в течение 48 часов.",
    "faq.joinCost": "Сколько стоит партнёрство?",
    "faq.joinCostA": "Регистрация бесплатна — в период бета-тестирования все партнёры на плане Starter. По мере роста платформы появятся планы Standard (€{standardFee}/мес.) и Premium (€{premiumFee}/мес.), снижающие комиссию и позволяющие добавлять больше локаций. Комиссия зависит от плана: {starterRate}% (Starter), {standardRate}% (Standard), {premiumRate}% (Premium).",
    "faq.canEditPrices": "Могу ли я управлять ценами?",
    "faq.canEditPricesA": "Да, партнёры могут управлять ценами, доступностью и описаниями услуг.",
    "faq.noAnswer": "Не нашли ответ?",
    "faq.contactUs": "Свяжитесь с нами",

    "homeFaq.q1": "Как работает бронирование через Ruumly?",
    "homeFaq.a1": "Найдите услугу, выберите даты, введите данные и подтвердите. Всё в одном месте.",
    "homeFaq.q2": "Действительно ли через нас дешевле?",
