    "privacy.s1.text": "Ruumly (OÜ Ruumly, reģistrācijas nr. 16XXXXXX) ir atbildīgs par jūsu personas datu apstrādi. Šī politika izskaidro, kādus datus mēs vācam un kā tos izmantojam.",
    "privacy.s1.title": "1. Vispārīga informācija",
    "privacy.s2.items": "Vārds and cieslēgtstact details (email, phieslēgtse)|Kieslēgtsts data (username, password hash)|Rezervācija data and pakalpojums usage vēsture|Atrašanās vieta data (for searches)|Device and browser data (via cookies)|Payment data (processed through secure payment providers)",
    "privacy.s2.title": "2. Kādus datus mēs vācam?",
    "privacy.s3.items": "Pakalpojums provisiieslēgts and booking pārvaldietment|Improving user pieredze|Marketing communicatiieslēgtss (with cieslēgtssent ieslēgtsly)|Fulfilling legal obligatiieslēgtss|Ensuring platform security",
    "privacy.s3.title": "3. Kā mēs izmantojam jūsu datus?",
    "privacy.s4.text": "Mēs kopīgojam datus ar: pakalpojumu sniedzējiem (jūsu rezervācijai), maksājumu apstrādātājiem un analītikas rīkiem (Google Analytics).",
    "privacy.s4.title": "4. Datu koplietošana",
    "privacy.s5.intro": "Under GDPR, you have the right to:",
    "privacy.s5.items": "Access jūsu persieslēgtsal data|Request correctiieslēgts or deletiieslēgts of data|Restrict data apstrādā|Data portability|Fails a complaint with the Data Protectiieslēgts Inspectorate",
    "privacy.s5.title": "5. Jūsu tiesības",
    "privacy.s6.text": "Mēs glabājam jūsu datus, kamēr jums ir aktīvs konts vai kamēr to prasa likums. Pēc konta dzēšanas dati tiek anonimizēti.",
    "privacy.s6.title": "6. Datu glabāšana",
    "privacy.s7.text": "Mēs izmantojam SSL šifrēšanu, drošus serverus un regulāras drošības pārbaudes, lai aizsargātu jūsu datus.",
    "privacy.s7.title": "7. Drošība",
